'use client';
import { useState } from 'react';
import Link from 'next/link';
import { useAuth } from '@/context/AuthContext';
import { User, Activity, Search, ChevronDown, Calendar, LogOut } from 'lucide-react';
import LoginModal from './LoginModal';

export default function Navbar() {
  const { user, logout } = useAuth();
  const [showLogin, setShowLogin] = useState(false);
  const [showDropdown, setShowDropdown] = useState(false);

  return (
    <>
      <nav className="glass" style={{ 
        position: 'fixed', 
        top: 0, 
        left: 0, 
        right: 0, 
        zIndex: 1000, 
        height: 'var(--header-height)',
        borderBottom: '1px solid rgba(255,255,255,0.05)'
      }}>
        <div className="container" style={{ 
          height: '100%', 
          display: 'flex', 
          alignItems: 'center', 
          justifyContent: 'space-between' 
        }}>
          <Link href="/" style={{ 
            fontSize: '1.8rem', 
            fontWeight: 'bold', 
            display: 'flex', 
            alignItems: 'center', 
            gap: '10px' 
          }}>
             <div style={{ background: 'var(--primary)', padding: '6px', borderRadius: '8px', display: 'flex' }}>
               <Activity size={24} color="#fff" />
             </div>
             <span className="text-gradient">Suvidha</span>
          </Link>
          
          <div className="desktop-menu" style={{ display: 'flex', gap: '2rem', alignItems: 'center' }}>
               <Link href="/" className="nav-item">Home</Link>
               <Link href="/lab-tests" className="nav-item">Lab Tests</Link>
               <Link href="/hospitals" className="nav-item">Hospital Services</Link>
               <Link href="/offers" className="nav-item" style={{ color: 'var(--accent)' }}>Offers</Link>
          </div>

          <div style={{ display: 'flex', gap: '1.5rem', alignItems: 'center' }}>
              <div style={{ position: 'relative' }}>
                  <Search size={22} style={{ color: 'var(--text-muted)' }} />
              </div>
              
              {user ? (
                <div style={{ position: 'relative' }}>
                   <button 
                      onClick={() => setShowDropdown(!showDropdown)}
                      style={{ 
                        background: 'transparent', 
                        border: 'none', 
                        display: 'flex', 
                        alignItems: 'center', 
                        gap: '8px', 
                        cursor: 'pointer',
                        color: 'var(--primary)',
                        fontSize: '0.9rem',
                        fontWeight: '500'
                      }}
                   >
                     <User size={18} />
                     <span>Hi, {user.phone}</span>
                     <ChevronDown size={14} />
                   </button>

                   {showDropdown && (
                     <div className="glass" style={{ 
                        position: 'absolute', 
                        top: '150%', 
                        right: 0, 
                        width: '200px', 
                        padding: '0.5rem', 
                        borderRadius: '12px',
                        display: 'flex',
                        flexDirection: 'column',
                        gap: '4px',
                        border: '1px solid rgba(255,255,255,0.1)'
                     }}>
                        <Link href="/profile" 
                          onClick={() => setShowDropdown(false)}
                          style={{ 
                            padding: '0.8rem 1rem', 
                            borderRadius: '8px', 
                            display: 'flex', 
                            alignItems: 'center', 
                            gap: '10px',
                            color: '#fff',
                            transition: 'background 0.2s' 
                          }}
                          onMouseOver={(e) => e.currentTarget.style.background = 'rgba(255,255,255,0.05)'}
                          onMouseOut={(e) => e.currentTarget.style.background = 'transparent'}
                        >
                           <Calendar size={16} /> My Bookings
                        </Link>
                        <div style={{ height: '1px', background: 'rgba(255,255,255,0.1)', margin: '4px 0' }}></div>
                        <button 
                          onClick={() => { logout(); setShowDropdown(false); }}
                          style={{ 
                            padding: '0.8rem 1rem', 
                            borderRadius: '8px', 
                            display: 'flex', 
                            alignItems: 'center', 
                            gap: '10px',
                            color: '#ff6b6b',
                            background: 'transparent',
                            border: 'none',
                            cursor: 'pointer',
                            width: '100%',
                            textAlign: 'left',
                            fontSize: '1rem'
                          }}
                          onMouseOver={(e) => e.currentTarget.style.background = 'rgba(255, 107, 107, 0.1)'}
                          onMouseOut={(e) => e.currentTarget.style.background = 'transparent'}
                        >
                           <LogOut size={16} /> Logout
                        </button>
                     </div>
                   )}
                </div>
              ) : (
                <button 
                  onClick={() => setShowLogin(true)}
                  className="btn btn-primary" 
                  style={{ padding: '0.5rem 1rem', fontSize: '0.9rem' }}
               >
                  Login
                </button>
              )}
          </div>
        </div>

        <style jsx>{`
          .nav-item {
             color: var(--text-muted);
             font-weight: 500;
             transition: all 0.2s;
             font-size: 0.95rem;
          }
          .nav-item:hover {
             color: var(--primary);
          }
          @media (max-width: 768px) {
             .desktop-menu { display: none !important; }
          }
        `}</style>
      </nav>
      <LoginModal isOpen={showLogin} onClose={() => setShowLogin(false)} />
    </>
  );
}
